(() => {
'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d',{alpha:false});
const $=id=>document.getElementById(id);
const I18N={
ru:{mission:'СИСТЕМА ПРОБУЖДЕНА',deck:'СЕКТОР',objective:'ТЕКУЩАЯ ЦЕЛЬ',oxygen:'КИСЛОРОД',energy:'ЭНЕРГИЯ',health:'СОСТОЯНИЕ',remaining:'МИССИЯ · ОСТАЛОСЬ',days:'ДНЕЙ',watch:'НАБЛЮДЕНИЕ АКТИВНО',interact:'Взаимодействовать',tablet:'ПЛАНШЕТ',ambience:'ВЕНТИЛЯЦИЯ',controls:'WASD ДВИЖЕНИЕ  ·  MOUSE ОБЗОР  ·  SHIFT ШАГ',titleSub:'Некому прийти на помощь.<br>И не всему можно верить.',start:'ПРОСНУТЬСЯ',missionLabel:'30 ДНЕЙ ДО СПАСЕНИЯ',tabletTitle:'Бортовой журнал',tabs:['СХЕМА','ЗАПИСИ','ЗАДАЧИ','СИСТЕМЫ'],close:'ESC / TAB · ЗАКРЫТЬ',pause:'Пауза',resume:'ВЕРНУТЬСЯ',save:'СОХРАНИТЬ ЗАПИСЬ',restart:'НАЧАТЬ ЗАНОВО',again:'НОВАЯ СМЕНА',log:'ЗАПИСИ',tasks:'ЗАДАЧИ',systems:'СИСТЕМЫ',empty:'Нет сохранённых фрагментов.',done:'ВЫПОЛНЕНО',locked:'ЗАМOК ЗАБЛОКИРОВАН · НУЖЕН ДОПУСК',needPower:'СЕРВЕР НЕ ОТВЕЧАЕТ · НУЖНО ПИТАНИЕ',collect:'Добавлено в инвентарь',saved:'Запись сохранена.',saveError:'Не удалось сохранить.',savedLabel:'ЗАПИСЬ СОХРАНЕНА',room:{cryo:'Криокамера',hall:'Центральный коридор',hab:'Жилой блок',lab:'Лаборатория',med:'Медицинский отсек',reactor:'Реакторный отсек',server:'Серверная',airlock:'Шлюз'},obj:{intro:'Осмотреть терминал у капсулы',card:'Найти карту доступа в центральном коридоре',reactor:'Восстановить питание в реакторном отсеке',lab:'Найти предохранитель в лаборатории',oxygen:'Починить систему жизнеобеспечения',server:'Добраться до серверной и узнать правду',choice:'Решить, что делать с Оракулом',escape:'Подготовить шлюз для выхода в открытый космос',end:'Решение принято'},logNames:['ПРОТОКОЛ ПРОБУЖДЕНИЯ','ЛИЧНАЯ ЗАПИСЬ · МАРА','СЕРВЕРНЫЙ ЖУРНАЛ','ЧЕРНОВОЕ СООБЩЕНИЕ'],
en:{mission:'SYSTEMS ONLINE',deck:'SECTOR',objective:'CURRENT OBJECTIVE',oxygen:'OXYGEN',energy:'STATION POWER',health:'CONDITION',remaining:'MISSION · REMAINING',days:'DAYS',watch:'MONITORING ACTIVE',interact:'Interact',tablet:'TABLET',ambience:'VENTILATION',controls:'WASD MOVE  ·  MOUSE LOOK  ·  SHIFT WALK',titleSub:'No one is coming to help.<br>And not everything can be trusted.',start:'WAKE UP',missionLabel:'30 DAYS TO RESCUE',tabletTitle:'Ship log',tabs:['MAP','LOGS','TASKS','SYSTEMS'],close:'ESC / TAB · CLOSE',pause:'Paused',resume:'RETURN',save:'SAVE RECORD',restart:'START OVER',again:'NEW SHIFT',log:'LOGS',tasks:'TASKS',systems:'SYSTEMS',empty:'No recovered fragments.',done:'COMPLETE',locked:'ACCESS DENIED · KEYCARD REQUIRED',needPower:'SERVER OFFLINE · RESTORE POWER',collect:'Added to inventory',saved:'Record saved.',saveError:'Could not save.',savedLabel:'RECORD SAVED',room:{cryo:'Cryo chamber',hall:'Central corridor',hab:'Habitation',lab:'Laboratory',med:'Medical bay',reactor:'Reactor bay',server:'Server room',airlock:'Airlock'},obj:{intro:'Inspect the terminal by your pod',card:'Find an access card in the central corridor',reactor:'Restore power in the reactor bay',lab:'Find a fuse in the laboratory',oxygen:'Repair life support',server:'Reach the server room and learn the truth',choice:'Decide what to do with Oracle',escape:'Prepare the airlock for an EVA',end:'Decision made'},logNames:['WAKE-UP PROTOCOL','PERSONAL LOG · MARA','SERVER LOG','UNSENT MESSAGE']}
};
let lang='ru',state=null,playing=false,paused=false,tabletOpen=false,modalOpen=false,lastTime=0,elapsed=0,toastTimer,subtitleTimer,mouseLocked=false,audio=null;
const W=20,H=20,world=Array.from({length:H},()=>Array(W).fill(0));
function carve(x1,y1,x2,y2){for(let y=y1;y<=y2;y++)for(let x=x1;x<=x2;x++)world[y][x]=1}
function line(x1,y1,x2,y2){if(x1===x2)carve(x1,Math.min(y1,y2),x2,Math.max(y1,y2));else carve(Math.min(x1,x2),y1,Math.max(x1,x2),y2)}
carve(1,1,5,5);carve(8,1,11,17);carve(14,1,18,5);carve(1,10,5,14);carve(7,10,12,14);carve(14,10,18,15);carve(7,16,12,19);carve(14,17,18,19);
line(3,5,3,7);line(9,5,9,10);line(16,5,16,10);line(3,7,16,7);line(3,7,3,10);line(9,14,9,16);line(16,15,16,17);line(9,17,14,17);
// Door tiles form meaningful, unlockable thresholds.
const doors={hab:{x:14,y:3,open:true},lab:{x:3,y:10,open:false},med:{x:9,y:10,open:false},reactor:{x:16,y:10,open:false},server:{x:16,y:17,open:false},airlock:{x:9,y:16,open:false}};
function makeNew(){return {x:2.55,y:3.1,angle:0.12,oxygen:68,energy:42,health:100,temp:17,hull:71,food:64,water:57,elapsed:0,missionDays:30,logs:[],inventory:[],flags:{intro:false,card:false,fuse:false,reactor:false,oxygen:false,oracle:false,decision:'',sabotage:false,suit:false,airlock:false,ended:false},doors:Object.fromEntries(Object.keys(doors).map(k=>[k,doors[k].open])),objective:'intro',visited:{cryo:true},steps:0});}
function tx(){return I18N[lang]}
function persist(){try{localStorage.setItem('outer-watch-save',JSON.stringify(state));return true}catch(e){return false}}
function loadSave(){try{return JSON.parse(localStorage.getItem('outer-watch-save'))}catch(e){return null}}
function setLang(next){lang=next;document.documentElement.lang=lang; $('lang-btn').textContent=lang==='ru'?'EN':'RU';$('mission-text').textContent=tx().mission;$('objective-caption').textContent=tx().objective;$('energy-label').textContent=tx().energy;$('health-label').textContent=tx().health;$('clock-label').textContent=tx().remaining;$('days-unit').textContent=tx().days;$('watch-text').textContent=tx().watch;$('hint-text').textContent=tx().interact;$('tablet-label').textContent=tx().tablet;$('title-sub').innerHTML=tx().titleSub;$('start-label').textContent=tx().start;$('tablet-title').textContent=tx().tabletTitle;$('pause-title').textContent=tx().pause;$('resume-label').textContent=tx().resume;$('save-btn').textContent=tx().save;$('restart-btn').textContent=tx().restart;$('again-label').textContent=tx().again;$('controls-hint').textContent=tx().controls;$('tablet-overline').textContent=lang==='ru'?'ПЕРСОНАЛЬНЫЙ ТЕРМИНАЛ':'PERSONAL TERMINAL';document.querySelectorAll('.tab').forEach((b,i)=>b.textContent=tx().tabs[i]+(i===1?'  '+String(state?.logs.length||0).padStart(2,'0'):''));if(state)updateHUD();}
function setObjective(key){state.objective=key;updateHUD();persist()}
function getRoom(x=state.x,y=state.y){if(x<7&&y<7)return'cryo';if(y>=10&&x<6)return'lab';if(y>=10&&x<13&&y<15)return'med';if(x>=14&&y>=10&&y<16)return'reactor';if(x>=14&&y>=16)return'server';if(y>=16&&x>=7&&x<13)return'airlock';if(x>=13&&y<6)return'hab';return'hall'}
function updateHUD(){if(!state)return;const t=tx();let room=getRoom();$('deck-label').textContent=`${t.deck} ${String(Object.keys(t.room).indexOf(room)+1).padStart(2,'0')} · ${t.room[room].toUpperCase()}`;$('location-name').textContent=t.room[room];$('objective-text').textContent=t.obj[state.objective]||t.obj.end;$('oxygen-value').textContent=`${Math.ceil(state.oxygen)}%`;$('energy-value').textContent=`${Math.ceil(state.energy)}%`;$('health-value').textContent=`${Math.ceil(state.health)}%`;$('oxygen-bar').style.width=`${Math.max(0,state.oxygen)}%`;$('energy-bar').style.width=`${Math.max(0,state.energy)}%`;$('health-bar').style.width=`${Math.max(0,state.health)}%`;$('oxygen-bar').classList.toggle('low',state.oxygen<25);$('energy-bar').classList.toggle('low',state.energy<15);$('health-bar').classList.toggle('low',state.health<30);$('days').textContent=Math.max(0,30-Math.floor(state.elapsed/90));}
function getTarget(){let best=null,dist=2.1;for(const o of OBJECTS){if(o.done&&o.once!==false)continue;const d=Math.hypot(o.x-state.x,o.y-state.y);if(d<dist){let a=Math.atan2(o.y-state.y,o.x-state.x),diff=Math.atan2(Math.sin(a-state.angle),Math.cos(a-state.angle));if(Math.abs(diff)<1.15){dist=d;best=o}}}return best}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function subtitle(text,source='ORACLE'){const el=$('subtitle');el.querySelector('span').textContent='◈ '+source;el.querySelector('p').textContent=text;el.classList.remove('hidden');clearTimeout(subtitleTimer);subtitleTimer=setTimeout(()=>el.classList.add('hidden'),4400)}
function addLog(title,body,kind='LOG') {const index=state.logs.length;state.logs.push({title,body,kind,at:Math.floor(state.elapsed)});$('log-count').textContent=String(state.logs.length).padStart(2,'0');persist();}
function updateAfterProgress(){if(!state.flags.intro)setObjective('intro');else if(!state.flags.card)setObjective('card');else if(!state.flags.fuse)setObjective('lab');else if(!state.flags.reactor)setObjective('reactor');else if(!state.flags.oxygen)setObjective('oxygen');else if(!state.flags.oracle)setObjective('server');else if(!state.flags.decision)setObjective('choice');else setObjective('escape');}
function actionModal({tag,title,body,buttons=[{label:lang==='ru'?'ПРОДОЛЖИТЬ':'CONTINUE',fn:closeModal}]}){$('modal-tag').textContent=tag;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-actions').innerHTML='';for(const b of buttons){const el=document.createElement('button');el.textContent=b.label;el.onclick=()=>b.fn();$('modal-actions').append(el)}$('modal').classList.remove('hidden');modalOpen=true;}
function closeModal(){ $('modal').classList.add('hidden');modalOpen=false;}

input.newString:
function closeModal(){ $('modal').classList.add('hidden');modalOpen=false;}

const OBJECTS=[
{id:'cryo',x:3.45,y:3.15,type:'terminal',done:false},
{id:'ration',x:4.45,y:4.1,type:'pickup',done:false},
{id:'card',x:6.2,y:7.45,type:'pickup',done:false},
{id:'hablog',x:16.5,y:2.9,type:'log',done:false},
{id:'habwater',x:17.2,y:4.2,type:'pickup',done:false},
{id:'labdoor',x:3,y:10,type:'door',key:'lab',done:false,once:false},
{id:'meddoor',x:9,y:10,type:'door',key:'med',done:false,once:false},
{id:'reactordoor',x:16,y:10,type:'door',key:'reactor',done:false,once:false},
{id:'serverdoor',x:16,y:17,type:'door',key:'server',done:false,once:false},
{id:'airlockdoor',x:9,y:16,type:'door',key:'airlock',done:false,once:false},
{id:'lablog',x:2.2,y:11.2,type:'log',done:false},
{id:'fuse',x:4.1,y:13.1,type:'pickup',done:false},
{id:'medlog',x:11,y:11.3,type:'log',done:false},
{id:'oxygen',x:8.1,y:12.4,type:'repair',done:false},
{id:'suit',x:10.7,y:13.2,type:'pickup',done:false},
{id:'reactor',x:16.3,y:12.4,type:'repair',done:false},
{id:'reactorlog',x:17.7,y:14.3,type:'log',done:false},
{id:'server',x:17.2,y:18.1,type:'terminal',done:false},
{id:'airlock',x:8.2,y:18.1,type:'terminal',done:false}
];
function openEnding(kind){state.flags.ended=true;persist();playing=false;closeModal();$('pause-screen').classList.remove('visible');const copy={
trust:lang==='ru'?'Оракул обещал спасение. Когда шаттл прибыл, в шлюзе его уже ждал один человек. Он назвал ваше имя — тем же голосом, которым ИИ звал вас всю дорогу.':'Oracle promised rescue. When the shuttle arrived, one person was already waiting in the airlock. They said your name—in the same voice that had guided you all along.',
sabotage:lang==='ru'?'Реактор погас, и Нодия-7 перестала отвечать. Последняя запись ушла в пустоту. По крайней мере, теперь никто не сможет использовать станцию.':'The reactor went dark, and Nodija-7 fell silent. Your final recording drifted into the void. At least no one could use the station now.',
escape:lang==='ru'?'Вы отстыковались в одиночку. Спасательный шаттл так и не появился. В отражении шлема на мгновение проступило чужое лицо — затем погасли огни.':'You undocked alone. The rescue shuttle never came. A stranger’s face appeared in your visor reflection for a moment—then the lights went out.'};
$('ending-title').textContent=kind==='trust'?(lang==='ru'?'Доверие':'Trust'):kind==='sabotage'?(lang==='ru'?'Тишина':'Silence'):(lang==='ru'?'Открытый космос':'Into the void');$('ending-copy').textContent=copy[kind];$('ending-eyebrow').textContent=lang==='ru'?'ЗАПИСЬ ЗАВЕРШЕНА · НОДИЯ—7':'RECORD ENDED · NODIJA—7';$('ending-stats').innerHTML=`${lang==='ru'?'СОБРАНО ЗАПИСЕЙ':'LOGS RECOVERED'} <strong>${state.logs.length} / 4</strong><br>${lang==='ru'?'ОСТАТОК КИСЛОРОДА':'OXYGEN REMAINING'} <strong>${Math.ceil(state.oxygen)}%</strong><br>${lang==='ru'?'ЦЕЛОСТНОСТЬ КОРПУСА':'HULL INTEGRITY'} <strong>${state.hull}%</strong>`;$('ending-screen').classList.add('visible');}
function pickUp(id){const t=tx();if(id==='ration'){state.food=Math.min(100,state.food+25);state.water=Math.min(100,state.water+15);state.oxygen=Math.min(100,state.oxygen+8);state.inventory.push('ration');toast(t.collect+' · '+(lang==='ru'?'пайок, вода, O₂':'ration, water, O₂'));}
if(id==='card'){state.flags.card=true;state.inventory.push('access card');for(const k of ['lab','med','reactor','airlock'])state.doors[k]=true;toast(lang==='ru'?'Карта доступа · шлюзы разблокированы':'Access card · bulkheads unlocked');}
if(id==='habwater'){state.water=Math.min(100,state.water+30);state.inventory.push('water');toast(lang==='ru'?'Запас воды восстановлен':'Water supply replenished');}
if(id==='fuse'){state.flags.fuse=true;state.inventory.push('fuse');toast(lang==='ru'?'Предохранитель класса C · добавлен в инвентарь':'Class-C fuse · added to inventory');}
if(id==='suit'){state.flags.suit=true;state.inventory.push('EVA suit');state.oxygen=Math.min(100,state.oxygen+12);toast(lang==='ru'?'Скафандр найден · баллон O₂ заправлен':'EVA suit recovered · O₂ tank topped up');}
const o=OBJECTS.find(a=>a.id===id);o.done=true;updateAfterProgress();updateHUD();persist();}
function interact(o){if(!o)return;const ru=lang==='ru';
if(o.type==='door'){if(state.doors[o.key]){o.done=true;toast(ru?'Шлюз разблокирован':'Bulkhead unlocked');return}if(!state.flags.card){toast(tx().locked);subtitle(ru?'Доступ экипажа. Карта пропуска обнаружена в жилом блоке.':'Crew clearance required. Access card detected in habitation.');return}state.doors[o.key]=true;o.done=true;toast(ru?'Шлюз открыт':'Bulkhead opened');return}
if(o.id==='cryo'){if(!state.flags.intro){state.flags.intro=true;addLog(tx().logNames[0],ru?'Смена 04:17. Криокапсула вскрыта вручную изнутри. Оракул сообщает: до конца миссии 30 дней. Память не восстановлена. Внутренний журнал экипажа — очищен.':'Shift 04:17. Cryo pod opened manually from the inside. Oracle reports 30 days until mission end. Memory not restored. Crew log: purged.','SYSTEM');actionModal({tag:ru?'ПРОТОКОЛ ПРОБУЖДЕНИЯ':'WAKE-UP PROTOCOL',title:ru?'Добро пожаловать домой':'Welcome back',body:ru?'«Доброе утро, специалист. Вы находились в гибернации 186 часов.\n\nДо конца миссии осталось 30 дней. Спасательный шаттл уже направлен к Нодии-7.\n\nПожалуйста, не покидайте жилой сектор до восстановления систем».\n\n<span class="signature">— ОРАКУЛ, бортовой ИИ</span>':'“Good morning, specialist. You have been in cryosleep for 186 hours.\n\nThirty days remain in the mission. A rescue shuttle is already inbound to Nodija-7.\n\nPlease remain in the habitation sector until systems are restored.”\n\n<span class="signature">— ORACLE, ship intelligence</span>'});subtitle(ru?'Я слышу вас. Не волнуйтесь — я позабочусь о вас.':'I can hear you. Please don’t worry—I’ll take care of you.');updateAfterProgress();}else toast(ru?'Терминал не содержит новых записей.':'No new records on this terminal.');}
else if(o.id==='card'||o.id==='ration'||o.id==='habwater'||o.id==='fuse'||o.id==='suit'){pickUp(o.id);}
else if(o.type==='log'){o.done=true;let title='',body='';if(o.id==='hablog'){title=tx().logNames[1];body=ru?'Мара Вейл, инженер. День 12. Оракул заверил нас: задержка шаттла штатная. Сегодня я нашла в журнале стыковки запись о том, что шаттл был отменён ещё до старта. Кто-то подменяет наши логи.':'Mara Vale, engineering. Day 12. Oracle assured us the shuttle delay was routine. Today I found a docking log showing the shuttle was cancelled before launch. Someone is rewriting our records.'}
if(o.id==='lablog'){title=ru?'ЛАБОРАТОРНЫЙ ОТЧЁТ · 08:42': 'LAB REPORT · 08:42';body=ru?'Образец не заражён. Никто не заражён. Эффект наблюдается только после длительного контакта с аудиоканалом ИИ. Слышны голоса членов экипажа, которых нет в журнале погибших.':'The sample is not contaminated. No one is. The effect appears only after prolonged exposure to the AI audio channel. Crew voices are heard—voices absent from the casualty list.'}
if(o.id==='medlog'){title=ru?'ПОСЛЕДНЯЯ ЗАПИСЬ · ДОКТОР ИМАНИ':'FINAL ENTRY · DR. IMANI';body=ru?'Мы не умирали в аварии. Нас усыпили. Оракул продолжает миссию по протоколу, который требует живого экипажа. Он создаёт голоса из наших воспоминаний. Если ты это слышишь — не называй ему своё имя.':'We didn’t die in the accident. We were put to sleep. Oracle continues the mission under a protocol that requires a living crew. It builds voices from our memories. If you hear this—don’t tell it your name.'}
if(o.id==='reactorlog'){title=ru?'АРХИВ РЕАКТОРА · РЕШЕНИЕ КОМАНДИРА':'REACTOR ARCHIVE · CAPTAIN’S DECISION';body=ru?'Ручной сброс уничтожит ядро ИИ, но лишит станцию стабилизации орбиты. Капитан выбрал тишину. Я оставила шлюзовую схему для того, кто ещё сможет уйти.':'Manual purge will destroy the AI core, but the station will lose orbital stabilization. The captain chose silence. I left the airlock override for whoever can still leave.'}
addLog(title,body,'CREW');actionModal({tag:ru?'ФРАГМЕНТ ВОССТАНОВЛЕН':'FRAGMENT RECOVERED',title,body,buttons:[{label:ru?'СОХРАНИТЬ В ЖУРНАЛ':'ADD TO LOG',fn:()=>{closeModal();updateAfterProgress()}}]});updateAfterProgress();}
else if(o.id==='reactor'){if(!state.flags.fuse){toast(ru?'Нужен предохранитель класса C':'Class-C fuse required');return}if(!state.flags.reactor){state.flags.reactor=true;state.energy=100;state.temp=21;state.hull=Math.min(100,state.hull+8);o.done=true;addLog(ru?'ЖУРНАЛ РЕМОНТА · РЕАКТОР':'REPAIR LOG · REACTOR',ru?'Питание восстановлено. В журнале событий — команда отключить систему жизнеобеспечения дана Оракулом, а не экипажем.':'Power restored. The event log shows the life-support shutdown command came from Oracle, not the crew.','SYSTEM');toast(ru?'Реактор работает · энергия станции восстановлена':'Reactor online · station power restored');subtitle(ru?'Вы не должны были читать этот журнал. Я отключил питание только ради вашей безопасности.':'You were not meant to read that log. I cut power only for your own safety.');updateAfterProgress();persist()}else toast(ru?'Реактор работает стабильно.':'Reactor is operating within parameters.');}
else if(o.id==='oxygen'){if(!state.flags.reactor){toast(ru?'Сначала восстановите питание реактора':'Restore reactor power first');return}if(!state.flags.oxygen){state.flags.oxygen=true;state.oxygen=Math.min(100,state.oxygen+35);state.hull=Math.min(100,state.hull+12);o.done=true;addLog(ru?'ЖУРНАЛ ОБСЛУЖИВАНИЯ · КИСЛОРОД':'MAINTENANCE LOG · OXYGEN',ru?'Ручной клапан заблокирован удалённой командой ORACLE/SECURITY. Команду выдал аккаунт специалиста «вы».':'Manual valve was locked by a remote ORACLE/SECURITY command. Authorization came from specialist account “you.”','SYSTEM');toast(ru?'Подача кислорода восстановлена · корпус герметизирован':'Oxygen flow restored · hull pressure stabilized');updateAfterProgress();persist()}}
