const FOV=Math.PI/3.15,keys={};let cw=640,ch=360,zbuf=[];
function resize(){cw=640;ch=Math.max(300,Math.round(cw*innerHeight/innerWidth));canvas.width=cw;canvas.height=ch;}
window.addEventListener('resize',resize);resize();
function isWall(x,y){let gx=Math.floor(x),gy=Math.floor(y);if(gx<0||gy<0||gx>=W||gy>=H)return true;for(const [k,d] of Object.entries(doors))if(gx===d.x&&gy===d.y&&!state?.doors?.[k])return true;return world[gy][gx]===0;}
function cellRoom(x,y){return getRoom(x+.5,y+.5)}
function palette(room){return {cryo:[85,127,132],hall:[97,119,119],hab:[115,117,101],lab:[91,119,119],med:[107,131,129],reactor:[140,101,69],server:[90,91,117],airlock:[101,127,133]}[room]||[95,115,116]}
function render(){if(!state){drawTitleBackdrop();return}const w=cw,h=ch,half=h/2;let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#10191d');grad.addColorStop(.47,'#283438');grad.addColorStop(.5,'#202a2d');grad.addColorStop(1,'#080d10');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
// Ceiling ribs and floor perspective lines establish the modular station shell.
ctx.strokeStyle='rgba(180,206,203,.08)';ctx.lineWidth=1;for(let i=0;i<8;i++){let yy=half-55+i*7;ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(w,yy);ctx.stroke()}ctx.strokeStyle='rgba(147,171,168,.075)';for(let i=1;i<13;i++){let yy=half+Math.pow(i/13,1.8)*(h-half);ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(w,yy);ctx.stroke()}
