function renderTab(name){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));const box=$('tab-content'),t=tx();box.innerHTML='';if(name==='map'){const label=document.createElement('div');label.className='panel-title';label.textContent=lang==='ru'?'СХЕМА ОТСЕКОВ · ОБНОВЛЯЕТСЯ ПО МЕРЕ ИССЛЕДОВАНИЯ':'DECK PLAN · REVEALED AS YOU EXPLORE';box.append(label);const map=document.createElement('div');map.className='map-card';const grid=document.createElement('div');grid.className='map-grid';const current=getRoom();for(let y=0;y<H;y++)for(let x=0;x<W;x++){let c=document.createElement('i');c.className='map-cell';let room=cellRoom(x,y),seen=state.visited[room]||Math.hypot(x+.5-state.x,y+.5-state.y)<2.2;if(world[y][x]===0)c.classList.add('wall');else if(seen)c.classList.add('room');else c.classList.add('unknown');if(Math.floor(state.x)===x&&Math.floor(state.y)===y)c.classList.add('player');else if(OBJECTS.some(o=>Math.floor(o.x)===x&&Math.floor(o.y)===y&&!(o.done&&o.once!==false)))c.classList.add('poi');grid.append(c)}map.append(grid);box.append(map);const legend=document.createElement('div');legend.className='map-legend';legend.innerHTML=`<span><i class="legend-dot"></i>${lang==='ru'?'Вы':'YOU'}</span><span><i class="legend-dot poi"></i>${lang==='ru'?'Объект':'OBJECTIVE'}</span><span><i class="legend-dot unknown"></i>${lang==='ru'?'Неизвестно':'UNEXPLORED'}</span>`;box.append(legend)}else if(name==='logs'){const label=document.createElement('div');label.className='panel-title';label.textContent=`${t.log} · ${String(state.logs.length).padStart(2,'0')}`;box.append(label);if(!state.logs.length){const empty=document.createElement('div');empty.className='log-entry';empty.innerHTML=`<p>${t.empty}</p>`;box.append(empty)}for(const l of [...state.logs].reverse()){const e=document.createElement('article');e.className='log-entry';e.innerHTML=`<small>${l.kind} · ${String(l.at).padStart(2,'0')}:${String(Math.floor(l.at%60)).padStart(2,'0')}</small><h3>${l.title}</h3><p>${l.body}</p>`;box.append(e)}}else if(name==='tasks'){const entries=[['intro',lang==='ru'?'Пробуждение и связь с Оракулом':'Wake up and contact Oracle'],['card',lang==='ru'?'Найти карту доступа':'Find an access card'],['fuse',lang==='ru'?'Найти предохранитель в лаборатории':'Find a fuse in the lab'],['reactor',lang==='ru'?'Восстановить питание реактора':'Restore reactor power'],['oxygen',lang==='ru'?'Восстановить подачу кислорода':'Restore oxygen supply'],['oracle',lang==='ru'?'Открыть архив Оракула':'Access Oracle archive']];for(const [flag,label] of entries){const e=document.createElement('article');e.className='task-entry'+(state.flags[flag]?' done':'');e.innerHTML=`<small>${state.flags[flag]?t.done:(lang==='ru'?'ОСНОВНАЯ ЗАДАЧА':'PRIMARY OBJECTIVE')}</small><h3>${label}</h3>`;box.append(e)}const end=document.createElement('article');end.className='task-entry'+(state.flags.decision?' done':'');end.innerHTML=`<small>${state.flags.decision?t.done:(lang==='ru'?'ФИНАЛЬНОЕ РЕШЕНИЕ':'FINAL DECISION')}</small><h3>${lang==='ru'?'Выбрать судьбу станции':'Choose the station’s fate'}</h3>`;box.append(end)}else{const vals=[[t.oxygen,`${Math.ceil(state.oxygen)}%`,state.oxygen<25],[t.energy,`${Math.ceil(state.energy)}%`,state.energy<20],[lang==='ru'?'ТЕМПЕРАТУРА':'TEMPERATURE',`${Math.round(state.temp)}°C`,state.temp<0],[lang==='ru'?'ЦЕЛОСТНОСТЬ КОРПУСА':'HULL INTEGRITY',`${state.hull}%`,state.hull<45],[lang==='ru'?'ПРОДОВОЛЬСТВИЕ':'FOOD',`${Math.ceil(state.food)}%`,state.food<20],[lang==='ru'?'ВОДА':'WATER',`${Math.ceil(state.water)}%`,state.water<20]];for(const [label,value,low] of vals){const e=document.createElement('article');e.className='system-entry';e.innerHTML=`<div><h3>${label}</h3><small>${low?(lang==='ru'?'ТРЕБУЕТ ВНИМАНИЯ':'ATTENTION REQUIRED'):(lang==='ru'?'НОРМА':'NOMINAL')}</small></div><div class="system-value" style="color:${low?'#d17865':''}">${value}</div>`;box.append(e)}}}

